import {createWorkbench} from './workbench.js';
/* Sonic Workshop review prototype. No external scripts, generation, tracking, or provider calls. */
const $ = (q, root=document) => root.querySelector(q);
const newId = () => { const b = crypto.getRandomValues(new Uint8Array(16)); b[6]=(b[6]&15)|64; b[8]=(b[8]&63)|128; return Array.from(b,(v,i)=>([4,6,8,10].includes(i)?'-':'')+v.toString(16).padStart(2,'0')).join(''); };
const csrf = $('meta[name="mm-csrf"]').content;
const audio = $('#audio');
const escapeHTML = (x='') => String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e = escapeHTML;
const icons={music:'M6 3v13a3 3 0 1 1-2-2.83V6l14-3v10a3 3 0 1 1-2-2.83V1L6 3',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',layers:'m3 7 9-4 9 4-9 4-9-4 M3 12l9 4 9-4 M3 17l9 4 9-4',spark:'m12 2 2.7 7.3L22 12l-7.3 2.7L12 22l-2.7-7.3L2 12l7.3-2.7L12 2',mic:'M9 6a3 3 0 0 1 6 0v6a3 3 0 0 1-6 0V6 M5 10v2a7 7 0 0 0 14 0v-2 M12 19v3 M8 22h8',headphones:'M3 14v-2a9 9 0 0 1 18 0v2 M3 12h4v9H3z M17 12h4v9h-4z',link:'m10 13 4-4 M8 16l-2 2a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0 M14 8l2-2a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0',search:'M20 20l-5-5 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',plus:'M12 4v16 M4 12h16',arrow:'M4 12h16 M14 6l6 6-6 6',chevron:'m9 5 7 7-7 7',back:'M20 12H4 M10 6l-6 6 6 6',play:'m8 4 13 8-13 8V4',pause:'M7 4v16 M17 4v16',lock:'M6 10h12v11H6z M8 10V6a4 4 0 0 1 8 0v4',unlock:'M6 10h12v11H6z M8 10V6a4 4 0 0 1 8 0',copy:'M8 8h12v13H8z M4 16H2V2h13v2',download:'M12 2v14 M6 10l6 6 6-6 M3 16v6h18v-6',upload:'M12 16V2 M6 8l6-6 6 6 M3 16v6h18v-6',close:'M5 5l14 14 M19 5 5 19',check:'m4 12 5 5L20 6',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',clock:'M12 6v6l4 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',git:'M6 3v12a5 5 0 0 0 5 5h7 M6 8h7a5 5 0 0 0 5-5 M3 3h6 M16 18l3 2-3 2',settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',heart:'M12 21 3 12a6 6 0 0 1 9-8 6 6 0 0 1 9 8l-9 9',note:'M4 3h16v18H4z M8 8h8 M8 12h8 M8 16h5',book:'M12 5c-4-3-7-2-10-1v15c4-1 7-1 10 2 3-3 6-3 10-2V4c-3-1-6-2-10 1v16',external:'M14 3h7v7 M21 3 10 14 M10 3H3v18h18v-7',volume:'M3 9h4l5-4v14l-5-4H3z M16 8a6 6 0 0 1 0 8 M19 5a10 10 0 0 1 0 14'};
function icon(name, cls=''){ return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.music}"/></svg>`; }
const fmt = v => `${Math.floor((v||0)/60)}:${String(Math.floor((v||0)%60)).padStart(2,'0')}`;
let state, instruments=[], capabilities=[], page='worlds', tab='arrange', selected='recipe_ridgeline', section='expansion', chosenTransform='horn-led', playing='take_diag_a', compare='take_diag_b', singer='singer_ember', search='', libraryFilter='all', waveformCache={}, region={start:6,end:12}, modalReturnFocus=null;
let compiled=null, busy=false;
const wb=createWorkbench({state:()=>state,instruments:()=>instruments,e,icon,button:(...x)=>button(...x),command:(...x)=>command(...x),render:()=>render(),toast,modal:openModal,closeModal,download,newId,audio,selectReference:()=>{playing='take_rowan_original';selected='recipe_rowan_anchor';audio.pause();audioLoadToken++;audio.removeAttribute('src');audio.load();delete audio.dataset.take;},openRecipe:async id=>{selected=id;page='workshop';tab='arrange';await refresh();},play:async(id,start,end)=>{await loadAudio(id,false);audio.currentTime=start;stopAt=end;await audio.play();render();}});
const recipe=()=>state.recipes.find(r=>r.id===selected)||state.recipes[0];
const inst=id=>instruments.find(x=>x.id===id)||{name:id,color:'mint',family:'Instrument',behavior:''};
const take=id=>state.takes.find(x=>x.id===id);
const button=(label,action,extra='',kind='secondary')=>`<button class="btn ${kind}" data-action="${action}" ${extra}>${label}</button>`;
const pill=(label,color='')=>`<span class="pill ${color}">${e(label)}</span>`;
const empty=(title,desc,action='')=>`<div class="empty">${icon('music')}<h3>${e(title)}</h3><p>${e(desc)}</p>${action}</div>`;
function toast(msg,error=false){const t=$('#toast');t.textContent=msg;t.className=`show ${error?'error':''}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',5500);}
async function fetchJSON(path,options={}){const res=await fetch(path,{...options,headers:{'X-MM-CSRF':csrf,...options.headers}});const data=await res.json();if(!res.ok){const err=new Error(data.error?.message||'Request failed.');err.code=data.error?.code;throw err;}return data;}
async function command(operation,input={},mutation=false){if(mutation&&busy)throw new Error('An edit is still being saved.');if(mutation)busy=true;try{const envelope={operation,input};if(mutation)Object.assign(envelope,{expected_sequence:state.sequence,idempotency_key:newId()});const d=await fetchJSON('/api/commands',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(envelope)});if(mutation)state=await fetchJSON('/api/state');return d.result;}catch(err){if(err.code==='stale_revision'){state=await fetchJSON('/api/state');render();}throw err;}finally{if(mutation)busy=false;}}
function download(name,obj){const blob=new Blob([typeof obj==='string'?obj:JSON.stringify(obj,null,2)],{type:typeof obj==='string'?'text/plain':'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function compile(){try{compiled=await command('prompt.compile',{recipe_id:recipe().id});}catch(err){compiled={error:err.message};}}
function cover(seed=0,size=''){return `<span class="cover cover-${seed%4} ${size}" aria-hidden="true"><svg viewBox="0 0 140 140"><circle cx="82" cy="58" r="41"/><circle cx="82" cy="58" r="32"/><circle cx="82" cy="58" r="23"/><path d="M-5 118 28 77 59 114 95 54 146 118 M-5 132 30 98 61 126 99 76 146 132 M-5 102 26 56 56 87 91 31 146 104"/><path d="M12 14v19 M3 24h19"/></svg></span>`;}
function instrumentArt(id){const x=inst(id);let path='M26 8v43 M32 8v43 M23 8h12 M20 47c-14 8-8 31 9 31s23-23 9-31c-8-7-8-18-8-18 M24 8v45 M34 8v45 M19 62h21';if(x.family.includes('Winds')||x.family.includes('reeds'))path='m18 68 29-55 6 3-29 55z M30 49l5 2 M35 40l5 2 M40 31l5 2';if(x.family==='Brass')path='M48 15 40 14 27 42 M41 16l10 4 M33 42a19 19 0 1 0 7 15 M33 42l16-5 7 14-19 2 M31 52a9 9 0 1 0 2 12';if(x.family.includes('percussion')||x.family.includes('Lamell'))path='M11 29h43v33H11z M16 20v50 M24 20v50 M32 20v50 M40 20v50 M48 20v50 M7 73h53';return `<span class="instrument-art ${x.color}"><svg viewBox="0 0 64 88" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="${path}"/></svg></span>`;}
function nav(){return `<aside class="sidebar"><a class="brand" href="#" data-action="nav" data-page="workshop"><span class="brandmark"><i></i><i></i><i></i><i></i><i></i></span><span>MeatyMusic<small>SONIC WORKSHOP</small></span></a><div class="nav-label">YOUR WORKSPACE</div><nav>${[['worlds','book','Musical worlds'],['workshop','grid','Workshop'],['library','layers','Library'],['explore','music','Instruments'],['voices','mic','Singers & voices']].map(([id,ic,label])=>`<button class="nav-item ${page===id?'active':''}" data-action="nav" data-page="${id}">${icon(ic)}${label}${id==='voices'?'<span class="new-dot"></span>':''}</button>`).join('')}</nav><div class="nav-label divide">HOUSE COLLECTIONS</div>${['Symphonic','Chamber','Roots','Experimental'].map((x,i)=>`<button class="collection-link" data-action="house" data-value="${x}"><span class="small-dot dot-${i}"></span>${x}</button>`).join('')}<div class="nav-label divide">RECENT IDEAS</div><div class="recent-nav">${state.recipes.slice(-4).reverse().map(r=>`<button class="recent-link ${r.id===selected?'selected':''}" data-action="open-recipe" data-id="${r.id}">${e(r.title)}<small>Recipe · r${r.revision.toString().padStart(2,'0')}</small></button>`).join('')}</div><div class="sidebar-bottom"><button class="nav-item ${page==='connections'?'active':''}" data-action="nav" data-page="connections">${icon('link')}Connections</button><button class="nav-item" data-action="export">${icon('download')}Export workspace</button><div class="profile"><span>NM</span><div>Nick<small>Local review workspace</small></div></div></div></aside>`;}
function shell(content){return `${nav()}<div class="main-shell"><header class="topbar"><div class="crumb">${icon('music')}<span>Studio</span><span>/</span><strong>${page==='worlds'?'Musical worlds':page==='workshop'?'Workshop':page==='voices'?'Singers & voices':page==='explore'?'Instrument atlas':page==='connections'?'Connections':'Your collection'}</strong></div><div class="top-right"><span class="local-badge"><i></i>Local prototype</span>${button(icon('info')+' Guide','guide','','quiet')}</div></header><main id="main" tabindex="-1">${content}</main></div>${player()}`;}
function heading(){const r=recipe();return `<section class="page-head"><div><div class="eyebrow">${e(r.identity)} <span> / </span> RECIPE r${r.revision.toString().padStart(2,'0')}</div><h1>${e(r.title)}</h1><div class="meta">${pill(r.vocal_mode==='instrumental'?'Instrumental':r.vocal_mode==='duet'?'Vocal duet':'Solo vocal')}${pill(r.bpm?`Target ${r.bpm} BPM`:'Free time')}${pill('Target '+r.meter)}<button class="inline-link" data-action="recipe-settings">Edit direction ${icon('settings')}</button></div></div><div class="head-actions">${button(icon('clock'),'history','aria-label="View recipe history"','icon-btn')}${button(icon('upload')+' Import take','import-take')}${button('Prepare handoff '+icon('arrow'),'handoff','','primary')}</div></section><div class="tabrow"><div class="tabs" role="tablist" aria-label="Recipe workspace">${[['arrange','Arrange'],['variations','Variations'],['listen','Listen & keep']].map(([id,label])=>`<button role="tab" aria-selected="${tab===id}" class="tab ${tab===id?'active':''}" data-action="tab" data-tab="${id}">${label}${id==='variations'?` <span class="count">${state.recipes.filter(x=>x.id===r.id||x.parent?.id===r.id).length}</span>`:''}</button>`).join('')}</div><span class="muted small">${icon('check')}Saved locally · ${state.events.length} local edits</span></div>`;}
function arrange(){const r=recipe();const sec=r.sections.find(x=>x.id===section)||r.sections[0];section=sec.id;const parts=r.parts.filter(p=>sec.parts.includes(p.id));return `${heading()}<div class="workspace-grid"><div class="workspace-main"><div class="section-heading"><div><h2>Shape the journey</h2><p>Section intentions, not editable audio tracks.</p></div>${button(icon(sec.locked?'lock':'unlock')+(sec.locked?' Pinned':' Pin section'),'toggle-pin',`data-id="${sec.id}"`,'quiet')}</div><div class="arc">${r.sections.map((s,i)=>`<button class="arc-card ${s.id===section?'active':''}" data-action="section" data-id="${s.id}"><span class="arc-number">0${i+1}${s.locked?icon('lock'):''}</span><strong>${e(s.name)}</strong><span>${e(s.description)}</span><div class="arc-line"><i style="width:${[18,50,88,30][i%4]}%"></i></div></button>`).join('')}</div><div class="arc-note">${icon('git')}A small idea grows into an ensemble, then finds its way home.</div><div class="section-heading ensemble-heading"><div class="title-inline"><h2>The ensemble</h2>${pill(sec.name,'mint')}</div>${button(icon('plus')+' Add instrument','add-instrument')}</div><div class="part-grid">${parts.map(p=>{const i=inst(p.instrument);return `<button class="part-card ${i.color}" data-action="edit-part" data-id="${p.id}">${instrumentArt(p.instrument)}<div><div class="part-role">${e(sec.roles?.[p.id]||p.role)}</div><h3>${e(i.name)}</h3><p>${e(p.behavior)}</p></div>${icon('chevron')}</button>`;}).join('')}</div><div class="bottom-note">${icon('info')}Instruments have jobs. Swap the player without rewriting the whole piece.</div><div class="mini-section"><div><span class="eyebrow">THE CHARACTER</span><p>${e(r.roots)}</p></div>${button('Tune the feel '+icon('settings'),'recipe-settings','','quiet')}</div></div><aside class="inspector"><div class="eyebrow mint-text">TRY A NEW DIRECTION</div><h2 class="serif">Keep the idea.<br>Change the voice.</h2><p class="muted">Explore one musical change while leaving the original intact.</p><div class="transform-options">${[['horn-led','Brass carries the horizon','Change the expansion lead.'],['chamber','Bring it into the room','Reduce orchestral layers.'],['bowed-lead','Let the melody breathe','Try a sustained bowed lead.']].map(([id,name,desc])=>`<button class="transform ${chosenTransform===id?'selected':''}" data-action="select-transform" data-id="${id}"><span class="radio-mark"></span><span><strong>${name}</strong><small>${desc}</small></span></button>`).join('')}</div><div class="preserved"><div class="eyebrow">PRESERVED IN THE RECIPE</div><p>${icon('lock')}Rhythm${r.locks.includes('rhythm')?' pinned':' unchanged by these operations'}</p><p>${icon('check')}Original recipe and recordings</p><p>${icon('check')}Pinned section intentions</p></div><div class="inspector-spacer"></div><p class="micro">Changes affect the next recipe, not the recording currently playing.</p>${button('Preview variation '+icon('arrow'),'preview-variation','','primary full')}</aside></div>`;}
function variations(){const r=recipe();const base=r.parent?state.recipes.find(x=>x.id===r.parent.id)||r:r;const family=state.recipes.filter(x=>x.id===base.id||x.parent?.id===base.id);return `${heading()}<div class="workspace-grid"><div><div class="section-heading"><div><h2>One idea. Several directions.</h2><p>Compare the musical changes before making another recording.</p></div>${button(icon('plus')+' Variation','preview-variation')}</div><div class="variant-list">${family.map((x,j)=>{const takes=state.takes.filter(t=>t.recipe_id===x.id);const h=state.handoffs.filter(h=>h.recipe_id===x.id).at(-1);return `<article class="variant-card ${x.id===r.id?'selected':''}"><div class="variant-top"><span class="letter">${String.fromCharCode(65+j)}</span><div><h3>${e(x.id===base.id?'Original':x.title.replace(base.title+' · ',''))}</h3><p>${x.parent?e(x.changes.join(' ')):'The original musical direction'}</p></div>${pill(h?(h.status==='prepared'?'Prepared · not sent':'Submission recorded'):x.id===base.id?'Baseline':'Draft',h?'amber':'')}</div><p>${e(x.sections.find(s=>s.id==='expansion')?.description||'')}</p><div class="variant-bottom"><span class="muted small">${takes.length?`${takes.length} ${takes.every(t=>t.source==='diagnostic')?'diagnostic takes':'attached takes'}`:'No audio attached'}</span><div>${button('Open recipe '+icon('arrow'),'open-recipe',`data-id="${x.id}"`,'quiet')}${button('Prepare','handoff-for',`data-id="${x.id}"`,'quiet')}</div></div></article>`;}).join('')}</div><div class="mini-section"><div><span class="eyebrow">PLAY FIRST. MEASURE WHEN IT MATTERS.</span><p>Mix ideas freely, or export an explicit experiment matrix.</p></div>${button('Plan experiment','experiment')}</div></div><aside class="inspector"><div class="title-inline"><h2>Suno</h2>${pill('Manual handoff','mint')}</div><p class="amber-text small">Prepared does not mean submitted.</p><hr><div class="field-heading"><strong>Style</strong><span class="mono">${compiled?.style_count||0} / 1,000</span></div><div class="prompt-preview">${e(compiled?.style||compiled?.error||'Compiling…')}</div>${button(icon('copy')+' Copy Style','copy-style','','secondary full')}<div class="field-heading"><strong>Excludes</strong><span class="small muted">Separate field</span></div><div class="excludes-preview">${e(compiled?.excludes||r.excludes)}</div>${button(icon('copy')+' Copy Excludes','copy-excludes','','quiet full')}<p class="micro">The exact recipe, text and recorded settings are frozen in each handoff.</p>${button('Review handoff '+icon('arrow'),'handoff','','primary full')}</aside></div>`;}
function wave(id,large=false){const points=waveformCache[id];if(!points)return `<div class="wave-loading">${icon('music')} ${take(id)?.audio?'Decode audio to see its actual waveform.':'No local audio attached.'}</div>`;const bars=points.map((h,i)=>`<line x1="${(i+.5)*800/points.length}" x2="${(i+.5)*800/points.length}" y1="${75-h*65}" y2="${75+h*65}"/>`).join('');return `<svg class="wave ${large?'large':''}" viewBox="0 0 800 150" preserveAspectRatio="none" role="img" aria-label="Waveform measured from the selected audio"><g stroke="currentColor" stroke-width="2">${bars}</g></svg>`;}
function listen(){const r=recipe();const takes=state.takes.filter(t=>t.recipe_id===r.id);const t=takes.find(t=>t.id===playing)||takes.find(t=>t.audio);const shown=t?.id;const moments=state.moments.filter(m=>m.recipe_id===r.id);return `${heading()}<div class="workspace-grid listen-layout"><div><div class="section-heading"><div><h2>Hear the relationship.</h2><p>Keep the moment you want to hear more of.</p></div>${button(icon('upload')+' Add a take','import-take')}</div>${t?`<div class="listening-panel"><div class="listen-top"><label>TAKE A<select id="take-select" data-change="select-take">${takes.map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${e(x.title)}</option>`).join('')}</select></label><span>${pill(t.source==='diagnostic'?'Diagnostic audio · not a generation':'Imported original','amber')}</span></div><div class="wave-area" data-wave="${shown}">${wave(shown,true)}<div class="selection-shade" style="left:${100*region.start/t.duration}%;width:${100*(region.end-region.start)/t.duration}%"></div></div><div class="wave-times"><span>0:00</span><span>${fmt(t.duration/4)}</span><span>${fmt(t.duration/2)}</span><span>${fmt(t.duration*.75)}</span><span>${fmt(t.duration)}</span></div><div class="selection-bar"><span class="lilac-text">Selected <b class="mono">${fmt(region.start)}–${fmt(region.end)}</b></span>${button(icon('play')+' Play selection','play-region',`data-id="${shown}"`,'quiet')}<span class="micro">Original bytes unchanged</span></div></div><div class="compare-controls"><label>COMPARE WITH<select id="compare-take">${takes.filter(x=>x.id!==t.id&&x.audio).map(x=>`<option value="${x.id}">${e(x.title)}</option>`).join('')}</select></label>${button('Switch A / B','switch-take','','secondary')}<p>Each take has its own time axis.<br>Automatic section alignment is not implemented.</p></div>`:empty('Bring the recording back','Attach an approved download or a link to this recipe.',button('Import a take','import-take','','primary'))}<div class="section-heading"><div><h2>Saved moments <span class="count">${moments.length}</span></h2><p>Each moment belongs to an exact recording.</p></div></div><div class="moment-grid">${moments.length?moments.map(m=>`<article class="moment-card"><div class="moment-title"><h3>${e(m.title)}</h3><span class="mono lilac-text">${fmt(m.start)}–${fmt(m.end)}</span></div><p>${e(m.note||'No note yet.')}</p><small>${e(take(m.take_id)?.title)}</small><div>${button(icon('play')+' Hear it','hear-moment',`data-id="${m.id}"`,'quiet')}${button('Build from here '+icon('arrow'),'moment-variation',`data-id="${m.id}"`,'quiet')}</div></article>`).join(''):empty('The good bit is worth keeping','Mark a range and save what you noticed.')}</div></div><aside class="inspector"><div class="eyebrow lilac-text">KEEP THIS MOMENT</div><h2 class="serif">Not just a favorite.<br>A starting point.</h2><p class="muted">A handoff. A texture. The answer beneath the melody.</p><label>Moment title<input id="moment-title" value="The handoff" maxlength="120"></label><div class="field-pair"><label>Start · seconds<input type="number" id="region-start" value="${region.start}" min="0" step="0.1" ${!t?'disabled':''}></label><label>End · seconds<input type="number" id="region-end" value="${region.end}" min="0" step="0.1" ${!t?'disabled':''}></label></div><label>What did you hear?<textarea id="moment-note" rows="4" placeholder="Love the melodic handoff. Keep the answering voice audible afterward."></textarea></label>${button(icon('heart')+' Save moment','save-moment',`data-id="${shown||''}" ${!t?'disabled':''}`,'primary full')}<hr><span class="eyebrow">THREE DIFFERENT QUESTIONS</span><p class="micro"><b>Did it follow the idea?</b><br><b>Did you enjoy it?</b><br><b>Where would you use it?</b><br><br>These notes are observations, not automatic quality scores.</p></aside></div>`;}
function library(){const q=search.toLowerCase();const rs=state.recipes.filter(r=>(r.title+' '+r.roots+' '+r.identity).toLowerCase().includes(q));const items=libraryFilter==='moments'?state.moments.filter(m=>(m.title+' '+m.note).toLowerCase().includes(q)):null;return `<section class="page-head"><div><div class="eyebrow">THE COLLECTION</div><h1>A world of your own.</h1><p class="lede">Recipes, recordings, and the discoveries between them.</p></div>${button(icon('plus')+' New recipe','new-recipe','','primary')}</section><div class="library-tools"><div class="filter-tabs">${[['all','Recipes'],['takes','Recordings'],['moments','Moments'],['handoffs','Handoffs']].map(([id,n])=>`<button class="filter ${libraryFilter===id?'active':''}" data-action="filter" data-id="${id}">${n}</button>`).join('')}</div><label class="search-box">${icon('search')}<input id="catalog-search" placeholder="Search your collection…" value="${e(search)}" aria-label="Search collection"></label></div>${libraryFilter==='all'?`<div class="recipe-grid">${rs.map((r,i)=>`<article class="recipe-tile">${cover(i,'large-cover')}<div class="tile-content"><div class="eyebrow">${e(r.identity)}</div><h2>${e(r.title)}</h2><p>${e(r.roots)}</p><div class="tile-bottom"><span>${r.parts.length} voices · ${r.sections.length} sections</span>${button('Open '+icon('arrow'),'open-recipe',`data-id="${r.id}"`,'quiet')}</div></div></article>`).join('')}</div>`:libraryFilter==='takes'?`<div class="record-list">${state.takes.filter(t=>t.title.toLowerCase().includes(q)).map(t=>`<div class="record-row">${cover(1)}<div><h3>${e(t.title)}</h3><p>${e(t.source==='diagnostic'?'Diagnostic fixture · synthesized, not generated':t.source==='link_only'?'Link only · audio not ingested':'Original local import')}</p></div><span class="mono">${t.duration?fmt(t.duration):'—'}</span>${button(icon(t.audio?'play':'external'),t.audio?'play-take':'external',t.audio?`data-id="${t.id}" aria-label="Play ${e(t.title)}"`:`data-url="${e(t.url)}" aria-label="Open provider link"`,'icon-btn')}</div>`).join('')}</div>`:libraryFilter==='moments'?`<div class="moment-grid">${items.length?items.map(m=>`<article class="moment-card"><h3>${e(m.title)}</h3><p>${e(m.note)}</p><span class="mono">${fmt(m.start)}–${fmt(m.end)}</span>${button('Open recipe','open-recipe',`data-id="${m.recipe_id}"`,'quiet')}</article>`).join(''):empty('Keep the useful moments','Your selected passages will live here, linked to their recordings.')}</div>`:`<div class="record-list">${state.handoffs.length?state.handoffs.map(h=>`<div class="record-row">${icon('copy')}<div><h3>${e(state.recipes.find(r=>r.id===h.recipe_id)?.title)}</h3><p>${e(h.id)} · recipe r${h.recipe_revision} · ${e(h.provider)}</p></div>${pill(h.status==='prepared'?'Prepared · not sent':'Submission recorded','amber')}${button('Open','open-handoff',`data-id="${h.id}"`)}</div>`).join(''):empty('No handoffs yet','Freeze a recipe, copy the fields, then connect the result when you return.')}</div>`}<div class="bottom-note">${icon('info')}Instrument tags describe requests. They are not automatically detected in recordings.</div>`;}
function explore(){const q=search.toLowerCase();const list=instruments.filter(i=>(i.name+' '+i.family+' '+i.context).toLowerCase().includes(q));return `<section class="page-head"><div><div class="eyebrow">INSTRUMENT ATLAS</div><h1>Different voices.<br>Unexpected conversations.</h1><p class="lede">Find a material, then give it a musical job.</p></div><label class="search-box">${icon('search')}<input id="instrument-search" placeholder="Try reeds, Asia, brass…" value="${e(search)}" aria-label="Search instruments"></label></section><div class="notice">${icon('info')}This starter atlas is an editorial prompt palette. Region labels are context, not authenticity guarantees or fixed musical rules.</div><div class="instrument-grid">${list.map(i=>`<article class="instrument-tile">${instrumentArt(i.id)}<span class="eyebrow">${e(i.family)}</span><h2>${e(i.name)}</h2><p>${e(i.behavior)}</p><div class="instrument-context">${e(i.context)}</div>${button('Add to recipe '+icon('plus'),'add-specific',`data-id="${i.id}"`,'quiet full')}</article>`).join('')}</div>`;}
function voices(){const s=state.singers.find(s=>s.id===singer)||state.singers[0];const r=recipe();return `<section class="page-head"><div><div class="eyebrow">SINGERS & VOICES</div><h1>A character before a voice.</h1><p class="lede">Shape the singer. Audition the speech. Verify the singing separately.</p></div>${button(icon('upload')+' Import Voice Lab bundle','import-voice')}</section><div class="voice-flow"><span>${icon('mic')}Singer direction</span>${icon('arrow')}<span>Voice Lab · curate</span>${icon('arrow')}<span>Promotion bundle</span>${icon('arrow')}<span>Estate Voice · speak</span><span class="flow-note">Singing identity is a separate binding.</span></div><div class="voice-grid"><div class="voice-main"><div class="singer-cards">${state.singers.map((x,j)=>`<button class="singer-card ${x.id===s.id?'selected':''}" data-action="singer-select" data-id="${x.id}"><div class="voice-orb orb-${j}">${icon('mic')}</div><div><span class="eyebrow">${e(x.role)}</span><h2>${e(x.name)}</h2><p>${e(x.register)} · ${e(x.character)}</p></div>${pill('Direction only','lilac')}</button>`).join('')}</div><section class="panel voice-editor"><div class="section-heading"><div><h2>The performance direction</h2><p>Creative intent—not a verified singer, range, or provider voice.</p></div>${pill('r'+s.revision)}</div><div class="form-grid"><label>Name<input id="s-name" value="${e(s.name)}" maxlength="120"></label><label>Target register<input id="s-register" value="${e(s.register)}" maxlength="100"></label><label class="span-2">Vocal character<input id="s-character" value="${e(s.character)}" maxlength="500"></label><label class="span-2">Phrasing & expression<textarea id="s-phrasing" rows="2" maxlength="500">${e(s.phrasing)}</textarea></label><label>Vibrato<input id="s-vibrato" value="${e(s.vibrato)}" maxlength="300"></label><label>Language<input id="s-language" value="${e(s.language)}" maxlength="100"></label><label class="span-2">Linked speech reference<select id="s-binding"><option value="">No speech reference linked</option>${state.voice_bindings.map(b=>`<option value="${e(b.id)}" ${s.voice_ref===b.id?'selected':''}>${e(b.name)} · speech only</option>`).join('')}</select></label></div><div class="form-footer"><p>Linking a speech voice never marks singing identity as verified.</p>${button('Save direction','save-singer','','primary')}</div></section><div class="panel cast-panel"><div><h2>Cast in this recipe</h2><p>${e(r.title)}</p></div><select id="vocal-mode" aria-label="Recipe vocal mode" data-change="vocal-mode">${[['instrumental','Instrumental'],['solo','Solo lead'],['duet','Lead + answering voice']].map(([v,n])=>`<option value="${v}" ${r.vocal_mode===v?'selected':''}>${n}</option>`).join('')}</select>${pill(r.vocal_mode==='instrumental'?'Voices not in prompt':'Directions included','mint')}</div></div><aside class="inspector voice-inspector"><div class="eyebrow lilac-text">ONE IDENTITY. DIFFERENT CAPABILITIES.</div><h2 class="serif">Listen to who<br>it could become.</h2><div class="capability-line">${icon('check')}Character and delivery brief<span class="pill mint">Local</span></div><div class="capability-line">${icon('check')}Promotion metadata import<span class="pill mint">Local</span></div><div class="capability-line">${icon('info')}Live speech synthesis<span class="pill amber">Not wired</span></div><div class="capability-line">${icon('info')}Exact singing identity<span class="pill amber">Unverified</span></div><hr><p class="muted">Export a design brief for Voice Lab, or prepare reviewed speech for the estate service. Neither action generates audio.</p>${button('Export Voice Lab brief '+icon('download'),'export-voice-brief','','primary full')}${button('Prepare spoken audition','tts-brief','','secondary full')}<p class="micro">The voice-design brief is a proposed interchange, not a currently implemented Voice Lab import endpoint.</p><div class="imported-voices"><span class="eyebrow">LINKED PROMOTED VOICES</span>${state.voice_bindings.length?state.voice_bindings.map(v=>`<div class="binding-row"><strong>${e(v.name)}</strong><small>${e(v.provider)} · ${e(v.status)} · speech</small></div>`).join(''):'<p class="muted small">No Voice Lab bundle imported.</p>'}</div></aside></div>`;}
function connections(){return `<section class="page-head"><div><div class="eyebrow">CAPABILITIES & CONNECTIONS</div><h1>One workshop.<br>Different ways to make sound.</h1><p class="lede">A provider-neutral recipe, with honest edges around each tool.</p></div>${pill('No external calls','mint')}</section><div class="provider-grid">${capabilities.map(p=>`<article class="provider-card"><div class="provider-symbol">${icon(p.id==='voice-lab'||p.id==='aos-tts'?'mic':'music')}</div><div class="provider-head"><h2>${e(p.name)}</h2>${pill(p.status,p.route==='planned'?'amber':'mint')}</div><span class="eyebrow">${e(p.category)}</span><p>${e(p.description)}</p><div class="provider-limit">${icon('info')}<span>${e(p.singing)}</span></div>${p.id==='suno'?button('Prepare Suno handoff','handoff','','secondary full'):p.id==='eleven'?button('Export composition-plan draft','export-eleven','','secondary full'):p.id==='voice-lab'?button('Import promotion metadata','import-voice','','secondary full'):p.id==='aos-tts'?button('Prepare speech handoff','tts-brief','','secondary full'):'<div class="planned-caption">Contract proposed · live adapter not implemented</div>'}</article>`).join('')}</div><div class="panel endpoint-panel"><div><h2>Your estate surfaces</h2><p>Optional navigation links only. No credentials, API discovery, or remote actions in this prototype.</p></div><div class="form-grid"><label>Voice Lab URL<input id="voice-lab-url" type="url" placeholder="Configured by your estate operator" value="${e(state.settings.voice_lab_url)}"></label><label>Estate Voice URL<input id="tts-url" type="url" placeholder="Configured by your estate operator" value="${e(state.settings.aos_tts_url)}"></label></div><div class="form-footer">${button('Save links','save-links','','primary')}${state.settings.voice_lab_url?button('Open Voice Lab '+icon('external'),'external',`data-url="${e(state.settings.voice_lab_url)}"`):''}${state.settings.aos_tts_url?button('Open Estate Voice '+icon('external'),'external',`data-url="${e(state.settings.aos_tts_url)}"`):''}</div></div>`;}
function player(){const t=take(playing);const live=audio.dataset.take===playing;const shownTime=live?audio.currentTime:0;const shownDuration=live&&Number.isFinite(audio.duration)?audio.duration:t?.duration;return `<footer class="player"><div class="now-playing">${cover(2)}<div><div class="playing-source">${t?e(t.source==='diagnostic'?'DIAGNOSTIC AUDIO · NOT SUNO':t.source==='user_provided_reference'?'APPROVED REFERENCE · ORIGINAL':t.source==='local_import'?'YOUR IMPORTED ORIGINAL':'NO LOCAL AUDIO'):'NOTHING PLAYING'}</div><strong>${e(t?.title||'Choose a take to listen')}</strong><small>Editing: ${e(recipe().title)}</small></div></div><div class="transport"><button class="round-play" data-action="toggle-play" aria-label="${audio.paused?'Play':'Pause'}" ${!t?.audio?'disabled':''}>${icon(audio.paused?'play':'pause')}</button><span class="mono time-now">${fmt(shownTime)}</span><input id="seek" type="range" min="0" max="${shownDuration||1}" step="0.01" value="${shownTime||0}" aria-label="Seek recording"><span class="mono time-total">${fmt(shownDuration)}</span></div><div class="volume-control">${icon('volume')}<input id="volume" aria-label="Playback volume" type="range" min="0" max="1" step="0.01" value="${audio.volume}"></div><button class="player-open" data-action="go-listen" aria-label="Open listening room">${icon('headphones')}</button></footer>`;}
function render(){if(!state)return;$('#app').innerHTML=shell(page==='worlds'?wb.render():page==='workshop'?(tab==='arrange'?arrange():tab==='variations'?variations():listen()):page==='library'?library():page==='explore'?explore():page==='voices'?voices():connections());if(page==='worlds')wb.afterRender();if(page==='workshop'&&tab==='listen'){const t=take(playing);if(t?.audio)decodeWave(t);} }
async function refresh(){await compile();render();}
function openModal(title,content,footer='',wide=false){modalReturnFocus=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header><div><span class="eyebrow">SONIC WORKSHOP</span><h2 id="dialog-title">${e(title)}</h2></div><button class="btn icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></header><div class="modal-body">${content}</div>${footer?`<footer>${footer}</footer>`:''}</section></div>`;document.body.classList.add('modal-open');setTimeout(()=>$('#overlay input, #overlay textarea, #overlay select, #overlay button')?.focus(),10);}
function closeModal(){$('#overlay').innerHTML='';document.body.classList.remove('modal-open');modalReturnFocus?.focus();}
function handoffModal(){const r=recipe();if(compiled?.error){toast(compiled.error,true);return;}openModal('Take the idea to Suno',`<div class="notice mint-notice">${icon('info')}Manual handoff. This saves the exact text and recipe. Nothing is submitted automatically.</div><div class="field-heading"><strong>Style</strong><span id="live-count" class="mono">${compiled.style_count} / 1,000</span></div><textarea id="handoff-style" rows="7">${e(compiled.style)}</textarea><div class="field-heading"><strong>Excludes</strong><span>Copy separately</span></div><textarea id="handoff-excludes" rows="3" readonly>${e(compiled.excludes)}</textarea>${r.vocal_mode!=='instrumental'?`<label>Lyrics<textarea id="handoff-lyrics" rows="3" readonly>${e(compiled.lyrics||'No lyrics yet. Add them in Edit direction.')}</textarea></label>`:''}<div class="form-grid"><label>Model used in your account<input id="handoff-model" placeholder="Record the exact selection; do not assume"></label><label>Settings note<input id="handoff-settings" placeholder="Record sliders / persona / voice as used"></label></div><div class="micro">${compiled.omitted.length?'Omitted optional prose: '+e(compiled.omitted.join(' · ')):'No optional prose omitted.'}<br>Model and account capabilities are not probed. Text targets do not establish acoustic fidelity.</div>`,`${button(icon('copy')+' Style','copy-dialog-style')}${button(icon('copy')+' Excludes','copy-dialog-excludes')}${button('Save handoff '+icon('arrow'),'save-handoff','','primary')}`,true);}
function showHandoff(id){const h=state.handoffs.find(x=>x.id===id);openModal('Handoff recorded',`<div class="receipt-hero">${icon('check')}<h3>${h.status==='prepared'?'Prepared. Not submitted.':'Submission recorded by you.'}</h3><p class="mono">${e(h.id)}</p></div><div class="receipt-details"><p><span>Recipe</span><strong>${e(h.recipe_snapshot.title)} · r${h.recipe_revision}</strong></p><p><span>Style</span><strong>${h.prompt.style_count} / 1,000</strong></p><p><span>Provider calls</span><strong>0 from this prototype</strong></p></div><p class="micro">Prompt SHA-256: ${e(h.prompt.hash)}</p><label>Exact prepared style<textarea rows="5" readonly>${e(h.prompt.style)}</textarea></label><div class="notice">${icon('info')}Return with a provider link or an approved download. Attach it to this handoff to close the loop.</div>`,`${button('Export JSON','export-handoff',`data-id="${h.id}"`)}${button('Open Suno '+icon('external'),'external','data-url="https://suno.com/create"')}${h.status==='prepared'?button('Record submitted','submitted-dialog',`data-id="${h.id}"`):''}${button('Attach result','import-take',`data-handoff="${h.id}"`,'primary')}`,true);}
function importModal(handoffId=''){const r=recipe();const hs=state.handoffs.filter(x=>x.recipe_id===r.id);openModal('Bring a recording back',`<p class="muted">Files stay in this local workspace. A provider link is stored without fetching its audio.</p><label>Which handoff produced it?<select id="import-handoff"><option value="">No matching handoff / association unknown</option>${hs.map(h=>`<option value="${h.id}" ${h.id===handoffId?'selected':''}>${e(h.id)} · r${h.recipe_revision}</option>`).join('')}</select></label><label>Take title<input id="import-title" placeholder="e.g. Horn-led expansion · take 02" maxlength="160"></label><div class="upload-zone">${icon('upload')}<strong>Choose your approved audio file</strong><span>WAV, MP3, OGG, FLAC or M4A · under 40 MB</span><input id="import-file" type="file" accept="audio/*" aria-label="Select audio recording"></div><div class="or-divider">OR SAVE A LINK</div><label>Provider result URL<input id="import-url" type="url" placeholder="https://…"></label><label class="check-label"><input id="import-confirm" type="checkbox">I confirm the recipe association and have permission to store this file locally.</label><p class="micro">Linking or importing does not grant model-analysis, training, or cross-provider reuse rights. Unknown permissions remain unknown.</p>`,button('Attach result','save-import','','primary'),true);}
async function importAudio(){const f=$('#import-file').files[0];const url=$('#import-url').value.trim();if(!$('#import-confirm').checked)throw new Error('Confirm the local import and recipe association first.');if(f&&url)throw new Error('Choose a file or a link for this import, not both.');const title=$('#import-title').value.trim()||f?.name||'Linked take';const hid=$('#import-handoff').value;if(!f){if(!url)throw new Error('Choose audio or paste a provider link.');await command('take.link',{recipe_id:recipe().id,handoff_id:hid||null,title,url},true);}else{if(f.size>40*1024*1024)throw new Error('Audio must be under 40 MB.');const buffer=await f.arrayBuffer();const ctx=new AudioContext();let decoded;try{decoded=await ctx.decodeAudioData(buffer.slice(0));}finally{await ctx.close();}if(decoded.duration>7200)throw new Error('Audio must be under two hours.');const query=new URLSearchParams({recipe_id:recipe().id,handoff_id:hid,title,name:f.name,duration:String(decoded.duration),sequence:String(state.sequence)});const result=await fetchJSON('/api/uploads?'+query,{method:'POST',headers:{'Content-Type':'application/octet-stream','Idempotency-Key':newId()},body:buffer});state=await fetchJSON('/api/state');playing=result.result.id;loadAudio(playing,false);}closeModal();tab='listen';page='workshop';region={start:0,end:Math.min(6,take(playing)?.duration||6)};await refresh();toast('Result attached. Original audio is preserved.');}
async function decodeWave(t){if(waveformCache[t.id]||!t.audio)return;try{const bytes=await fetch(t.audio).then(r=>r.arrayBuffer());const ctx=new AudioContext();let b;try{b=await ctx.decodeAudioData(bytes);}finally{await ctx.close();}const data=b.getChannelData(0),step=Math.max(1,Math.floor(data.length/220)),peaks=[];let max=0;for(let i=0;i<220;i++){let p=0;for(let j=i*step;j<Math.min((i+1)*step,data.length);j+=Math.max(1,Math.floor(step/60)))p=Math.max(p,Math.abs(data[j]));peaks.push(p);max=Math.max(max,p);}waveformCache[t.id]=peaks.map(p=>Math.max(.015,p/(max||1)));const el=$(`[data-wave="${t.id}"]`);if(el){const shade=$('.selection-shade',el)?.outerHTML||'';el.innerHTML=wave(t.id,true)+shade;}}catch(err){toast('This audio could not be decoded for a waveform.',true);}}
let audioLoadToken=0, activeAudioBlob=null;
async function loadAudio(id,play=true){const t=take(id);if(!t?.audio){toast('No audio is attached to this take.');return;}playing=id;const request=++audioLoadToken;try{if(audio.dataset.take!==id){const res=await fetch(t.audio);if(!res.ok)throw new Error('Audio unavailable.');const blob=await res.blob();if(request!==audioLoadToken)return;if(activeAudioBlob)URL.revokeObjectURL(activeAudioBlob);activeAudioBlob=URL.createObjectURL(blob);audio.src=activeAudioBlob;audio.dataset.take=id;audio.load();await new Promise((resolve,reject)=>{audio.addEventListener('loadedmetadata',resolve,{once:true});audio.addEventListener('error',reject,{once:true});});}if(play)await audio.play();decodeWave(t);}catch(err){toast('Could not play the local audio. Press Play or check the imported file.',true);}}
let stopAt=null;audio.addEventListener('timeupdate',()=>{if(stopAt!==null&&audio.currentTime>=stopAt){audio.pause();stopAt=null;}if($('.time-now'))$('.time-now').textContent=fmt(audio.currentTime);if($('#seek'))$('#seek').value=audio.currentTime;});audio.addEventListener('loadedmetadata',()=>{if($('#seek'))$('#seek').max=audio.duration;if($('.time-total'))$('.time-total').textContent=fmt(audio.duration);});for(const event of ['play','pause','ended'])audio.addEventListener(event,()=>{const b=$('[data-action="toggle-play"]');if(b){b.innerHTML=icon(audio.paused?'play':'pause');b.setAttribute('aria-label',audio.paused?'Play':'Pause');}});
async function action(a,el){
 if(a.startsWith('wb-')){await wb.action(a,el);return;}
 switch(a){
 case 'nav':page=el.dataset.page;search='';await refresh();break;
 case 'house':page='library';libraryFilter='all';search='House / '+el.dataset.value;render();break;
 case 'open-recipe':selected=el.dataset.id;page='workshop';tab='arrange';section='expansion';await refresh();break;
 case 'tab':tab=el.dataset.tab;if(tab==='listen'){const ts=state.takes.filter(t=>t.recipe_id===recipe().id&&t.audio);if(!ts.some(t=>t.id===playing)&&ts.length)loadAudio(ts[0].id,false);region={start:0,end:Math.min(6,take(playing)?.duration||6)};}await refresh();break;
 case 'section':section=el.dataset.id;render();break;
 case 'toggle-pin':{const s=recipe().sections.find(s=>s.id===el.dataset.id);await command('recipe.section.update',{recipe_id:recipe().id,section_id:s.id,patch:{locked:!s.locked}},true);await refresh();toast(s.locked?'Section unpinned.':'Section pinned.');break;}
 case 'select-transform':chosenTransform=el.dataset.id;render();break;
 case 'preview-variation':{const p=await command('variation.plan',{recipe_id:recipe().id,transformation:chosenTransform});openModal('A small change. A new direction.',`<div class="change-columns"><section><span class="eyebrow amber-text">CHANGED</span>${p.changes.map(x=>`<p>${icon('arrow')}${e(x)}</p>`).join('')}</section><section><span class="eyebrow mint-text">PRESERVED</span>${p.preserved.map(x=>`<p>${icon('check')}${e(x)}</p>`).join('')}</section></div><div class="notice">${icon('info')}${e(p.notice)}</div>`,`${button('Cancel','close-modal')}${button('Apply as variation','apply-variation','','primary')}`);break;}
 case 'apply-variation':{const r=await command('variation.apply',{recipe_id:recipe().id,transformation:chosenTransform},true);selected=r.id;tab='variations';closeModal();await refresh();toast('New recipe created. Original remains unchanged.');break;}
 case 'recipe-settings':{const r=recipe();openModal('The musical direction',`<div class="form-grid"><label class="span-2">Recipe title<input id="r-title" value="${e(r.title)}" maxlength="120"></label><label class="span-2">Roots & musical language<input id="r-roots" value="${e(r.roots)}" maxlength="500"></label><label>Target BPM<input id="r-bpm" type="number" value="${r.bpm||''}" min="20" max="300" ${r.locks.includes('rhythm')?'disabled':''}></label><label>Target meter<input id="r-meter" value="${e(r.meter)}" ${r.locks.includes('rhythm')?'disabled':''}></label><label class="span-2 check-label"><input type="checkbox" id="rhythm-lock" ${r.locks.includes('rhythm')?'checked':''}>Pin rhythm. Uncheck and save before changing the target.</label><label class="span-2">Tonality · optional<input id="r-tonality" value="${e(r.tonality)}"></label><label class="span-2">Production character<textarea id="r-production" rows="2">${e(r.production)}</textarea></label><label class="span-2">Common Excludes<textarea id="r-excludes" rows="2">${e(r.excludes)}</textarea></label><label class="span-2">Lyrics · optional, up to 5,000 characters<textarea id="r-lyrics" rows="4" maxlength="5000">${e(r.lyrics)}</textarea></label></div>`,button('Save direction','save-recipe','','primary'),true);break;}
 case 'save-recipe':{const r=recipe();const patch={title:$('#r-title').value,roots:$('#r-roots').value,tonality:$('#r-tonality').value,production:$('#r-production').value,excludes:$('#r-excludes').value,lyrics:$('#r-lyrics').value,locks:$('#rhythm-lock').checked?['rhythm']:[]};if(!r.locks.includes('rhythm')){patch.bpm=$('#r-bpm').value?Number($('#r-bpm').value):null;patch.meter=$('#r-meter').value;}await command('recipe.update',{recipe_id:r.id,patch},true);closeModal();await refresh();toast('Direction saved as a new recipe revision.');break;}
 case 'edit-part':{const p=recipe().parts.find(p=>p.id===el.dataset.id);const locked=recipe().sections.filter(s=>s.locked&&s.parts.includes(p.id));openModal('A player with a purpose',`${locked.length?`<div class="notice">${icon('lock')}This part is in pinned ${e(locked.map(x=>x.name).join(', '))}. Unpin before editing.</div>`:''}<label>Instrument<select id="part-instrument">${instruments.map(i=>`<option value="${i.id}" ${i.id===p.instrument?'selected':''}>${e(i.name)} · ${e(i.family)}</option>`).join('')}</select></label><label>Musical role<select id="part-role">${['lead','answer','counterline','foundation','color','harmony','expansion','drone','punctuation'].map(x=>`<option ${x===p.role?'selected':''}>${x}</option>`).join('')}</select></label><label>What does it do?<textarea id="part-behavior" maxlength="160" rows="3">${e(p.behavior)}</textarea></label><p class="micro">Changing the instrument does not imply a cultural genre change or retune the recording.</p>`,button('Save part','save-part',`data-id="${p.id}" ${locked.length?'disabled':''}`,'primary'));break;}
 case 'save-part':await command('recipe.part.update',{recipe_id:recipe().id,part_id:el.dataset.id,patch:{instrument:$('#part-instrument').value,role:$('#part-role').value,behavior:$('#part-behavior').value}},true);closeModal();await refresh();toast('Part updated.');break;
 case 'add-instrument':openModal('Find a different voice',`<p class="muted">Add a supporting color to ${e(recipe().sections.find(s=>s.id===section)?.name)}. Assign its musical role next.</p><label class="search-box">${icon('search')}<input id="modal-instrument-search" placeholder="Search the instrument palette…" aria-label="Search instrument palette"></label><div class="instrument-picker">${instruments.map(i=>`<button class="picker-item" data-action="add-specific" data-id="${i.id}" data-search="${e((i.name+' '+i.context+' '+i.family).toLowerCase())}">${instrumentArt(i.id)}<span><strong>${e(i.name)}</strong><small>${e(i.context)} · ${e(i.family)}</small></span>${icon('plus')}</button>`).join('')}</div>`);break;
 case 'add-specific':await command('recipe.part.add',{recipe_id:recipe().id,section_id:section,instrument:el.dataset.id},true);closeModal();await refresh();toast(inst(el.dataset.id).name+' added to '+section+'.');break;
 case 'handoff-for':selected=el.dataset.id;await compile();handoffModal();break;
 case 'handoff':await compile();handoffModal();break;
 case 'copy-style':if(compiled?.error)throw new Error(compiled.error);await navigator.clipboard.writeText(compiled.style);toast('Style copied. No generation submitted.');break;
 case 'copy-excludes':await navigator.clipboard.writeText(compiled?.excludes||recipe().excludes);toast('Excludes copied separately.');break;
 case 'copy-dialog-style':await navigator.clipboard.writeText($('#handoff-style').value);toast('Style copied.');break;
 case 'copy-dialog-excludes':await navigator.clipboard.writeText($('#handoff-excludes').value);toast('Excludes copied.');break;
 case 'save-handoff':{const style=$('#handoff-style').value;const h=await command('handoff.create',{recipe_id:recipe().id,provider:'suno',...(style!==compiled.style?{style_override:style}:{}),settings:{model:$('#handoff-model').value||null,note:$('#handoff-settings').value}},true);showHandoff(h.id);render();break;}
 case 'open-handoff':showHandoff(el.dataset.id);break;
 case 'export-handoff':{const h=state.handoffs.find(x=>x.id===el.dataset.id);download(h.id+'.json',h);toast('Frozen handoff exported.');break;}
 case 'submitted-dialog':{const h=state.handoffs.find(x=>x.id===el.dataset.id);openModal('Record what you actually submitted',`<p class="muted">This is your attestation of work done outside this app, not a provider confirmation.</p><label>Actual Style<textarea id="actual-style" rows="7">${e(h.prompt.style)}</textarea></label><label>Actual settings note<input id="actual-settings" value="${e(h.settings.note||'')}"></label>`,button('Record submission','record-submitted',`data-id="${h.id}"`,'primary'),true);break;}
 case 'record-submitted':await command('handoff.record_submission',{handoff_id:el.dataset.id,actual_style:$('#actual-style').value,settings:{note:$('#actual-settings').value}},true);showHandoff(el.dataset.id);render();break;
 case 'import-take':importModal(el.dataset.handoff||'');break;
 case 'save-import':el.disabled=true;el.textContent='Validating local audio…';try{await importAudio();}finally{el.disabled=false;el.textContent='Attach result';}break;
 case 'toggle-play':stopAt=null;if(audio.paused){loadAudio(playing,true);}else audio.pause();break;
 case 'play-take':loadAudio(el.dataset.id,true);render();break;
 case 'play-region':{await loadAudio(el.dataset.id,false);audio.currentTime=region.start;stopAt=region.end;await audio.play();break;}
 case 'go-listen':page='workshop';tab='listen';if(take(playing))selected=take(playing).recipe_id;await refresh();break;
 case 'switch-take':{const id=$('#compare-take').value;if(!id)throw new Error('Attach a second audio take to compare.');const old=playing;loadAudio(id,true);compare=old;region={start:0,end:Math.min(6,take(id).duration)};render();break;}
 case 'save-moment':{const m=await command('moment.create',{take_id:el.dataset.id,title:$('#moment-title').value,start:Number($('#region-start').value),end:Number($('#region-end').value),note:$('#moment-note').value},true);render();toast('Moment saved against its exact recording.');break;}
 case 'hear-moment':{const m=state.moments.find(m=>m.id===el.dataset.id);await loadAudio(m.take_id,false);audio.currentTime=m.start;stopAt=m.end;await audio.play();break;}
 case 'moment-variation':{const r=await command('moment.to_variation',{moment_id:el.dataset.id},true);selected=r.id;tab='arrange';await refresh();toast('A new recipe references this moment. No audio was edited.');break;}
 case 'filter':libraryFilter=el.dataset.id;render();break;
 case 'new-recipe':openModal('Start a new idea',`<p class="muted">Start with the house ensemble and make it your own.</p><label>Recipe title<input id="new-title" placeholder="An idea worth hearing" maxlength="120"></label>`,button('Create recipe','create-recipe','','primary'));break;
 case 'create-recipe':{const r=await command('recipe.create',{title:$('#new-title').value},true);selected=r.id;page='workshop';tab='arrange';closeModal();await refresh();break;}
 case 'singer-select':singer=el.dataset.id;render();break;
 case 'save-singer':await command('singer.update',{singer_id:singer,patch:{name:$('#s-name').value,register:$('#s-register').value,character:$('#s-character').value,phrasing:$('#s-phrasing').value,vibrato:$('#s-vibrato').value,language:$('#s-language').value,voice_ref:$('#s-binding').value||null}},true);await refresh();toast('Singer direction saved. Singing identity remains unverified.');break;
 case 'export-voice-brief':{const brief=await command('voice.brief',{singer_id:singer});download('voice-design-brief-'+singer+'.json',brief);toast('Design brief exported. Voice Lab has not been changed.');break;}
 case 'import-voice':openModal('Link promoted Voice Lab voices',`<p class="muted">Import an existing <code>voice-lab.promotion-bundle</code> v1.0 JSON file. Provider voice IDs remain provider-scoped.</p><div class="upload-zone">${icon('upload')}<strong>Promotion bundle · JSON</strong><input type="file" id="voice-bundle-file" accept="application/json,.json"></div><div class="notice">${icon('info')}Read-only metadata import. No voice creation, promotion, provider call, or singing verification occurs.</div>`,button('Import metadata','save-voice-bundle','','primary'));break;
 case 'save-voice-bundle':{const f=$('#voice-bundle-file').files[0];if(!f)throw new Error('Select a promotion bundle.');if(f.size>500000)throw new Error('Bundle must be under 500 KB.');await command('voice.bundle.import',{bundle:JSON.parse(await f.text())},true);closeModal();render();toast('Voice metadata linked. Scope: speech only.');break;}
 case 'tts-brief':{if(!state.voice_bindings.length){toast('Import a promoted Voice Lab bundle first.',true);page='voices';render();return;}openModal('Prepare a spoken audition',`<p class="muted">A reviewed speech handoff for aos-tts. This is not singing synthesis and is not sent automatically.</p><label>Promoted voice<select id="tts-voice">${state.voice_bindings.map(v=>`<option value="${e(v.id)}">${e(v.name)} · ${e(v.provider)}</option>`).join('')}</select></label><label>Spoken audition text<textarea id="tts-text" rows="4" maxlength="5000">Keep the opening intimate. Let the second voice answer, then leave a little room before the orchestra arrives.</textarea></label><label class="check-label"><input type="checkbox" id="tts-reviewed">I have reviewed this text for the spoken audition.</label>`,button('Export speech handoff','export-tts','','primary'));break;}
 case 'export-tts':{const d=await command('tts.handoff',{voice_id:$('#tts-voice').value,text:$('#tts-text').value,reviewed:$('#tts-reviewed').checked});download('estate-voice-speech-handoff.json',d);closeModal();toast('Speech handoff exported. No request sent.');break;}
 case 'save-links':await command('settings.update',{voice_lab_url:$('#voice-lab-url').value,aos_tts_url:$('#tts-url').value},true);render();toast('Navigation links saved locally.');break;
 case 'export-eleven':{const d=await command('prompt.compile',{recipe_id:recipe().id,provider:'eleven'});download('eleven-composition-plan-draft.json',d);toast('Plan exported with editable section-duration placeholders.');break;}
 case 'external':{const u=new URL(el.dataset.url);if(!['https:','http:'].includes(u.protocol))throw new Error('Unsupported link.');window.open(u.href,'_blank','noopener,noreferrer');break;}
 case 'export':download('sonic-workshop-metadata-'+new Date().toISOString().slice(0,10)+'.json',await command('workspace.export'));toast('Metadata exported. Audio files stay in prototype/data/assets; include them in your backup.');break;
 case 'experiment':openModal('Make the question explicit',`<p class="muted">Plan only—no generations or charges. This exports a matrix for an agent or later batch adapter.</p><label>Question<input id="experiment-question" value="Does a brass expansion keep the plucked lead more audible?"></label><div class="form-grid"><label>Lead options<input id="experiment-leads" value="sarod, erhu, bass clarinet"></label><label>Accompaniment options<input id="experiment-beds" value="strings, horns"></label><label>Replicates per cell<input id="experiment-reps" type="number" value="2" min="1" max="10"></label></div><div class="notice">${icon('info')}Requested takes are not the same as provider requests. Budget must be confirmed before execution.</div>`,button('Export experiment plan','export-experiment','','primary'));break;
 case 'export-experiment':{const leads=$('#experiment-leads').value.split(',').map(x=>x.trim()).filter(Boolean),beds=$('#experiment-beds').value.split(',').map(x=>x.trim()).filter(Boolean),reps=Number($('#experiment-reps').value);if(!leads.length||!beds.length||reps<1||reps>10||leads.length*beds.length*reps>100)throw new Error('Use nonempty factors and keep the plan at 100 takes or fewer.');const d={schema:'meatymusic.experiment-plan.v1',status:'proposed_not_executed',question:$('#experiment-question').value,recipe_ref:{id:recipe().id,revision:recipe().revision},factors:{lead:leads,accompaniment:beds},replicates:reps,requested_takes:leads.length*beds.length*reps,provider_requests:null,cost:null,budget_approval:false};download('experiment-plan.json',d);closeModal();toast(d.requested_takes+' requested takes planned. None generated.');break;}
 case 'history':openModal('Recipe lineage',`<div class="history-list">${state.recipes.filter(x=>x.id===recipe().id||x.id===recipe().parent?.id).map(r=>`<div>${icon('git')}<span><strong>${e(r.title)} · r${r.revision}</strong><small>${r.parent?'Variation of '+e(r.parent.id):'Root recipe'}</small></span></div>`).join('')}${state.recipe_history.filter(x=>x.id===recipe().id).reverse().map(r=>`<div>${icon('clock')}<span><strong>Saved revision ${r.revision}</strong><small>${e(r.title)}</small></span></div>`).join('')}</div><p class="micro">Submitted handoffs retain their exact recipe snapshots even as the current draft changes.</p>`);break;
 case 'guide':openModal('A workshop, not a simulated generator',`<div class="guide-grid"><section><h3>Working here</h3><p>Edit roles and sections. Preview a reversible variation. Compile a budget-checked prompt. Freeze a handoff. Import audio, play it, and save exact moments. Link Voice Lab promotion metadata. Export voice-design and speech briefs.</p></section><section><h3>Explicitly not connected</h3><p>No Suno, ElevenLabs, Lyria, aos-tts, or Voice Lab calls. No AI audio analysis. No singing identity transfer. The original diagnostic recordings remain available. The optional Rowan seed additionally imports Nick’s actual approved recording and unverified MIDI, with separate evidence labels.</p></section></div><div class="notice">${icon('info')}Run the API and CLI against the same local command layer. This isolated review prototype is a reference for an additive MeatyMusic implementation, not a replacement for its production stack.</div><p class="micro">Metadata and original imports persist in the local data directory. Do not expose this loopback prototype as a public service.</p>`,'',true);break;
 case 'close-modal':closeModal();break;
 default:toast('This control is not implemented.',true);
 }
}
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-action]');if(!el)return;ev.preventDefault();action(el.dataset.action,el).catch(err=>toast(err.message,true));});
document.addEventListener('input',ev=>{const el=ev.target;if(el.id==='seek'){stopAt=null;audio.currentTime=Number(el.value);}if(el.id==='volume')audio.volume=Number(el.value);if(el.id==='handoff-style'){const n=el.value.length;$('#live-count').textContent=n+' / 1,000';$('#live-count').classList.toggle('error-text',n>1000);}if(el.id==='modal-instrument-search'){const q=el.value.toLowerCase();document.querySelectorAll('.picker-item').forEach(x=>x.hidden=!x.dataset.search.includes(q));}if(el.id==='catalog-search'||el.id==='instrument-search'){search=el.value;const id=el.id,pos=el.selectionStart;clearTimeout(action.searchTimer);action.searchTimer=setTimeout(()=>{render();const i=$('#'+id);i?.focus();i?.setSelectionRange(pos,pos);},220);}});
document.addEventListener('change',ev=>{const el=ev.target;(async()=>{if(el.dataset.change==='select-take'){loadAudio(el.value,false);region={start:0,end:Math.min(6,take(el.value)?.duration||6)};render();}if(el.dataset.change==='vocal-mode'){await command('recipe.update',{recipe_id:recipe().id,patch:{vocal_mode:el.value,singer_ids:el.value==='instrumental'?[]:el.value==='solo'?[singer]:state.singers.map(s=>s.id)}},true);await refresh();toast('Casting updated. Review prompt length before handoff.');}if(['region-start','region-end'].includes(el.id)){const a=Number($('#region-start').value),b=Number($('#region-end').value),d=take(playing)?.duration;if(a>=0&&b>a&&b<=d){region={start:a,end:b};const s=$('.selection-shade');if(s){s.style.left=100*a/d+'%';s.style.width=100*(b-a)/d+'%';}$('.selection-bar b').textContent=fmt(a)+'–'+fmt(b);}else toast('Keep the selected range inside the recording.',true);}if(el.id==='import-file'&&el.files[0]&&!$('#import-title').value)$('#import-title').value=el.files[0].name;})().catch(err=>toast(err.message,true));});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeModal();if(ev.key==='Tab'&&$('.modal')){const els=[...$('.modal').querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]')].filter(x=>!x.hidden);const first=els[0],last=els.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last?.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus();}}});
(async()=>{try{const results=await Promise.all([fetchJSON('/api/state'),fetchJSON('/api/catalog'),fetchJSON('/api/capabilities')]);state=results[0];instruments=results[1].instruments;capabilities=results[2].providers;audio.volume=.6;if(state.workbench?.seeded){playing='take_rowan_original';selected='recipe_rowan_anchor';}await refresh();loadAudio(playing,false);}catch(err){$('#app').innerHTML=`<div class="boot"><h1>Open the local workshop</h1><p>Start <code>python3 serve.py</code>, then open the loopback address it prints.</p><p>${e(err.message)}</p></div>`;}})();
